import sys
import base64
import json
import xml.etree.ElementTree as ET
from urllib.parse import unquote
from datetime import datetime

def decode_base64_safe(s):
    try:
        return base64.urlsafe_b64decode(s).decode('utf-8')
    except:
        return None

def parse_token(token_str):
    parts = token_str.split('.')
    if len(parts) != 3:
        return None

    part1 = decode_base64_safe(parts[0])
    part2 = decode_base64_safe(parts[1])
    part3 = decode_base64_safe(parts[2])

    if part1 is None or part2 is None or part3 is None:
        return None

    try:
        json_part1 = json.loads(part1)
        json_part2 = json.loads(part2)
    except:
        return None

    if not isinstance(json_part1, dict) or not isinstance(json_part2, dict):
        return None

    if 'sub' not in json_part2 or 'role' not in json_part2 or 'exp' not in json_part2:
        return None

    if not isinstance(json_part2['sub'], str) or not isinstance(json_part2['role'], str) or not isinstance(json_part2['exp'], int):
        return None

    if not isinstance(part3, str):
        return None

    return json_part1, json_part2, part3.strip()

def parse_policy(policy_path):
    try:
        tree = ET.parse(policy_path)
        root = tree.getroot()
        token_id = root.find('token-id').text.strip()
        rules = root.findall('rule')
        return token_id, rules
    except:
        return None, []

def evaluate_rule(action, condition, context):
    try:
        # Replace context keys with actual values
        expr = condition.replace('{', 'context[').replace('}', ']')
        return eval(expr, {'context': context})
    except:
        return False

def main():
    if len(sys.argv) != 4:
        print("deny")
        return

    policy_path = sys.argv[1]
    token_str = sys.argv[2]
    action = sys.argv[3]

    token_id, rules = parse_policy(policy_path)
    if token_id is None:
        print("deny")
        return

    token_data = parse_token(token_str)
    if token_data is None:
        print("deny")
        return

    json_part1, json_part2, token_value = token_data
    if token_value != token_id:
        print("deny")
        return

    current_time = int(datetime.now().timestamp())
    if json_part2['exp'] < current_time:
        print("deny")
        return

    granted = False
    for rule in rules:
        if rule.get('action') == action:
            condition = rule.get('condition', '')
            if evaluate_rule(action, condition, json_part2):
                granted = True
                break

    if granted:
        print("allow")
    else:
        print("deny")

if __name__ == "__main__":
