import sys
import xml.etree.ElementTree as ET
import base64
import json
import time
from urllib.parse import quote

def decode_base64_safe(s):
    return base64.urlsafe_b64decode(s.encode('ascii')).decode('ascii')

def parse_token(token):
    parts = token.split('.')
    if len(parts) != 3:
        return None
    decoded = json.loads(decode_base64_safe(parts[1]))
    return decoded

def parse_policy(policy_path):
    tree = ET.parse(policy_path)
    root = tree.getroot()
    token_id = root.find('token-id').text.strip()
    rules = root.findall('rule')
    return token_id, rules

def evaluate_condition(condition_str, context):
    try:
        return eval(condition_str, {}, context)
    except:
        return False

def check_policy(policy_path, token, action):
    token_decoded = parse_token(token)
    if not token_decoded:
        print('deny')
        return

    current_time = int(time.time())
    if token_decoded['exp'] < current_time:
        print('deny')
        return

    token_id, rules = parse_policy(policy_path)
    if token_decoded['sub'] != token_id:
        print('deny')
        return

    for rule in rules:
        rule_action = rule.get('action')
        rule_condition = rule.get('condition')
        if rule_action == action:
            context = {k: v for k, v in token_decoded.items()}
            if evaluate_condition(rule_condition, context):
                print('allow')
                return

    print('deny')

if __name__ == '__main__':
    if len(sys.argv) != 4:
        print('Usage: python policy_check.py <policy_path> <token> <action>')
