    check_policy(sys.argv[1], sys.argv[2], sys.argv[3])

import sys
import xml.etree.ElementTree as ET
import time

def parse_token(token):
    parts = token.split('.')
    if len(parts) != 2:
        return None
    try:
        first_part, second_part = parts
        return first_part.strip(), int(second_part)
    except ValueError:
        return None

def evaluate_condition(condition_str, user):
    try:
        return eval(condition_str, {'user': user})
    except:
        return False

def check_policy(policy_path, token, action):
    try:
        tree = ET.parse(policy_path)
        root = tree.getroot()
    except ET.ParseError:
        print("deny")
        return

    token_id = root.find('token-id').text.strip()
    token_parts = parse_token(token)
    if not token_parts:
        print("deny")
        return

    user, expiry = token_parts
    if user != token_id:
        print("deny")
        return

    current_time = int(time.time())
    if expiry < current_time:
        print("deny")
        return

    rules = root.findall('rule')
    granted = False

    for rule in rules:
        rule_action = rule.get('action')
        rule_condition = rule.get('condition')
