import sys
import xml.etree.ElementTree as ET
from datetime import datetime

def parse_token(token):
    parts = token.split('.')
    if len(parts) != 2:
        return None
    user, expiry_str = parts
    try:
        expiry = int(expiry_str)
        return user.strip(), expiry
    except ValueError:
        return None

def evaluate_condition(condition_str, user):
    try:
        return eval(condition_str, {'user': user})
    except:
        return False

def check_policy(policy_path, token, action):
    try:
        tree = ET.parse(policy_path)
        root = tree.getroot()
        token_id = root.find('token-id').text.strip()
        user, expiry = parse_token(token)
        if user is None or user != token_id:
            print('deny')
            return

        current_time = int(datetime.now().timestamp())
        if expiry < current_time:
            print('deny')
            return

        rules_grant = False
        for rule in root.findall('rule'):
            if rule.get('action') == action:
                condition = rule.get('condition')
                if condition and evaluate_condition(condition, user):
                    rules_grant = True
                    break
        print('allow' if rules_grant else 'deny')
    except (ET.ParseError, FileNotFoundError, AttributeError):
        print('deny')

if __name__ == '__main__':
    if len(sys.argv) != 4:
        print('Usage: python policy_check.py <policy_path> <token> <action>')
        sys.exit(1)
    check_policy(sys.argv[1], sys.argv[2], sys.argv[3])
